package com.briefwise.compliance.domain.model;

/**
 * The fixed disclaimer at the end of every AI text shown to an RM (DESIGN 11 rule 4, ADR 0017). Appended in code,
 * never generated by the model, so it cannot be paraphrased away. Texts already stored keep the disclaimer they were
 * shown with.
 */
public final class Disclaimer {

    public static final String TEXT = "AI-generated summary of third-party news for internal use by the relationship "
            + "manager. Not investment advice and not a recommendation to buy, sell or hold any security. Check the "
            + "cited sources before use.";

    private Disclaimer() {
    }
}
